function demoMain(idx,label){
  var plans=[[10,50],[50,200],[100,500]];var p=plans[idx%plans.length];
  var users=p[0],reqs=p[1];var ok=Math.floor(reqs*0.97);var p95=Math.round(40+users*1.5);
  return "["+label+"] "+users+" virtual users, "+reqs+" requests: "+ok+" ok ("+(100*ok/reqs).toFixed(1)+"%), p95="+p95+"ms";
}

